package com.enterpriseflow.service;
import com.enterpriseflow.entity.*; import com.enterpriseflow.repository.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class SearchService {private final UserRepository users;private final ProjectRepository projects;private final TaskRepository tasks;private final KnowledgeService knowledge;public SearchService(UserRepository u,ProjectRepository p,TaskRepository t,KnowledgeService k){users=u;projects=p;tasks=t;knowledge=k;}@Transactional(readOnly=true)public Map<String,Object> search(String email,String q){User u=users.findByEmail(email).orElseThrow();if(u.getMembershipStatus()!=MembershipStatus.ACTIVE||u.getCompany()==null)throw new AccessDeniedException("Your company access is not active.");String needle=q.trim().toLowerCase();if(needle.isEmpty())throw new IllegalArgumentException("A search query is required.");List<Map<String,Object>> ps=projects.findActiveByCompanyId(u.getCompany().getId()).stream().filter(p->u.getRole()==UserRole.ADMIN||p.hasMember(u.getId())).filter(p->p.getName().toLowerCase().contains(needle)||Objects.toString(p.getDescription(),"").toLowerCase().contains(needle)).map(p->Map.<String,Object>of("id",p.getId(),"name",p.getName(),"status",p.getStatus())).toList();List<Map<String,Object>> ts=tasks.findAll().stream().filter(t->t.getProject().getCompany().getId().equals(u.getCompany().getId())&&(u.getRole()==UserRole.ADMIN||t.getProject().hasMember(u.getId()))).filter(t->t.getTitle().toLowerCase().contains(needle)||Objects.toString(t.getDescription(),"").toLowerCase().contains(needle)).map(t->Map.<String,Object>of("id",t.getId(),"title",t.getTitle(),"project",t.getProject().getName(),"status",t.getStatus())).toList();List<Map<String,Object>> people=u.getRole()==UserRole.ADMIN?users.findByCompanyIdAndMembershipStatusOrderByCreatedAtDesc(u.getCompany().getId(),MembershipStatus.ACTIVE).stream().filter(x->x.getName().toLowerCase().contains(needle)||x.getEmail().toLowerCase().contains(needle)).map(x->Map.<String,Object>of("id",x.getId(),"name",x.getName(),"email",x.getEmail(),"role",x.getRole().name())).toList():List.of();return Map.of("projects",ps,"tasks",ts,"documents",knowledge.search(email,q),"users",people);}}
